from urllib.request import urlopen
for url in ('https://qcflow.cn/fusion-lab/','https://gitee.com/QCFlow/QLLVM'):
    try:
        with urlopen(url, timeout=10) as response:
            print(url, response.status, response.headers.get('content-type'))
            print(response.read(300).decode('utf-8', 'ignore').replace('\n', ' '))
    except Exception as exc:
        print(url, type(exc).__name__, exc)
